// --- COMPONENTES DO MÍMICO BLINDADO ---

const MimicoHeader = ({ subtitulo, regional }) => (
  <div className="bg-white grid grid-cols-12 items-center mb-2 uppercase text-black font-bold" >
    <div className="col-span-3 flex justify-end pr-6"><img src={LOGO_PARANA} alt="Brasão" className="h-24 w-auto object-contain" /></div>
    <div className="col-span-6 text-center text-[13px] leading-tight flex flex-col items-center">
      <p className="font-bold text-black uppercase">Estado do Paraná</p>
      <p className="font-bold text-black uppercase">Corpo de Bombeiros Militar</p>
      <p className="font-bold text-black uppercase">{regional || "CENTRO DE SUPRIMENTO E MANUTENÇÃO"}</p>
      {subtitulo && <p className="mt-2 text-[13px] border border-black py-0.5 bg-gray-200 px-4 font-bold text-black uppercase">{subtitulo}</p>}
    </div>
    <div className="col-span-3 flex justify-start pl-6"><img src={LOGO_CBMPR} alt="CBMPR" className="h-24 w-auto object-contain" /></div>
  </div>
);

const MimicoFormI = ({ data, update, readOnly }) => {
  const total = Object.values(data.scores).reduce((acc, obj: any) => acc + (obj?.v || 0), 0);
  return (
    <div className="bg-white text-black p-10 mx-auto text-[10px]" style={{ width: "210mm", minHeight: "297mm", fontFamily: "\"Inter\", \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif" }}>
      <MimicoHeader subtitulo="FORMULÁRIO I - TABELA DE PONTUAÇÃO" regional={data.agency.regional} />
      <div className="text-center font-bold text-[13px] uppercase mb-4 tracking-tighter text-black">
        {(!data.assetType || data.assetType === 'Veículo' || data.assetType === 'Automóvel') 
          ? 'AUTOMÓVEL/ÔNIBUS/CAMINHÃO/CORRELATOS' 
          : data.assetType === 'Embarcação' 
            ? 'EMBARCAÇÕES E MOTORES NÁUTICOS' 
            : 'AERONAVES E COMPONENTES'}
      </div>
      <div className="grid grid-cols-2 border border-black mb-4  divide-x border-black font-bold uppercase text-left">
        <div className="p-1 flex items-center text-black">MARCA/MODELO: <span className="ml-1 font-normal uppercase text-black">{data.vehicle.modelo}</span></div>
        <div className="p-1 flex items-center justify-end text-black">{(!data.assetType || data.assetType === 'Veículo' || data.assetType === 'Automóvel') ? 'PLACA' : data.assetType === 'Embarcação' ? 'INSCRIÇÃO' : 'PREFIXO'}: <span className="ml-1 font-normal uppercase text-black">{data.vehicle.placa || data.vehicle.inscricaoMarinha || data.vehicle.matriculaAeronave}</span></div>
      </div>
      <table className="w-full border-collapse border border-black  text-left">
        <thead><tr className="bg-gray-200 font-bold uppercase  text-black"><th className="border border-black p-1 text-center text-black ">PARTES</th><th className="border border-black p-1 text-black ">ITEM</th><th className="border border-black p-1 text-black ">CONDIÇÕES</th><th className="border border-black p-1 text-center text-black ">PONTOS</th><th className="border border-black p-1 text-center text-black ">NOTA</th></tr></thead>
        <tbody>
          {SCORE_CATEGORIES.map((part, pIdx) => {
            const partRowCount = part.items.reduce((acc, item) => acc + item.opts.length, 0);
            return (
              <React.Fragment key={pIdx}>
                {part.items.map((item, iIdx) => (
                  <React.Fragment key={iIdx}>
                    {item.opts.map((opt, oIdx) => (
                      <tr key={oIdx} className={!readOnly ? 'cursor-pointer hover:bg-gray-50' : ''} onClick={() => !readOnly && update({...data, scores: {...data.scores, [item.id]: opt}})}>
                        {iIdx === 0 && oIdx === 0 && <td rowSpan={partRowCount} className="border border-black p-1 font-bold text-center bg-white uppercase  text-black" style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)' }}>{part.id}</td>}
                        {oIdx === 0 && <td rowSpan={item.opts.length} className="border border-black p-1 font-bold bg-white text-black">{item.label}</td>}
                        <td className="border border-black p-1 font-normal  text-black">{opt.l}</td>
                        <td className="border border-black p-1 text-center font-normal text-black">{opt.v}</td>
                        {oIdx === 0 && <td rowSpan={item.opts.length} className="border border-black p-1 text-center font-bold  bg-white text-black">
                          {data.scores[item.id] !== undefined ? data.scores[item.id].v : ''}
                        </td>}
                      </tr>
                    ))}
                  </React.Fragment>
                ))}
              </React.Fragment>
            );
          })}
          <tr className="font-bold text-black"><td colSpan={4} className="border border-black p-1.5 text-right uppercase  text-black">TOTAL</td><td className="border border-black p-1.5 text-center text-[10px] font-bold text-black">{total}</td></tr>
        </tbody>
      </table>
      <div className="mt-4 border-2 border-black overflow-hidden">
        <table className="w-full border-collapse  text-center text-black">
          <thead className="bg-gray-100 uppercase font-bold text-black"><tr><th className="border border-black p-1 w-1/3 text-center text-black">NOTA</th><th className="border border-black p-1 w-1/3 text-center text-black">ESTADO</th><th className="border border-black p-1 w-1/3 text-center text-black">% TABELA FIPE</th></tr></thead>
          <tbody>
            {[
              { score: "91 a 100", label: "Ótimo", val: "50%", min: 91, max: 100 },
              { score: "61 a 90", label: "Bom", val: "35%", min: 61, max: 90 },
              { score: "41 a 60", label: "Regular", val: "25%", min: 41, max: 60 },
              { score: "1 a 40", label: "Péssimo", val: "15%", min: 1, max: 40 }
            ].map((r, idx) => (
              <tr key={idx} className={(total as number) >= r.min && (total as number) <= r.max ? "bg-yellow-50 font-bold" : ""}>
                <td className="border border-black p-1 text-black font-normal text-center">{r.score}</td>
                <td className="border border-black p-1 text-black font-normal text-center">{r.label}</td>
                <td className="border border-black p-1 text-black font-bold text-center">{r.val}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const ChecklistCol = ({ items, laudoData, update, readOnly }: { items: string[], laudoData: any, update: any, readOnly: boolean }) => (
  <div className="col-span-1 border-r last:border-r-0 border-black text-black">
    <div className="grid grid-cols-12 bg-gray-200 border-b border-black  font-bold text-center h-4 items-center uppercase"><div className="col-span-6 border-r border-black px-0.5 text-left pl-1 text-black ">DESCRIÇÃO</div><div className="col-span-2 border-r border-black ">SIM</div><div className="col-span-2 border-r border-black ">NÃO</div><div className="col-span-2 ">DANIF</div></div>
    {items.map((item, idx) => (
      <div key={idx} className="grid grid-cols-12 border-b border-black last:border-b-0 h-4 items-center ">
        <div className="col-span-6 px-1 truncate font-normal border-r border-black uppercase  leading-tight text-left text-black">{item}</div>
        {['S', 'N', 'D'].map(v => (
          <div key={v} onClick={() => !readOnly && update({...laudoData, checklist: {...laudoData.checklist, [item]: v}})} className={`col-span-2 border-r last:border-r-0 border-black text-center font-bold h-full flex items-center justify-center text-black ${readOnly ? '' : 'cursor-pointer hover:bg-gray-100'}`}>{laudoData.checklist[item] === v ? 'X' : ''}</div>
        ))}
      </div>
    ))}
  </div>
);

const MimicoFormIV = ({ data, update, readOnly }) => {
  const total = Object.values(data.scores).reduce((acc, obj: any) => acc + (obj?.v || 0), 0);
  const getPct = (s: any) => (s >= 91 ? 0.5 : s >= 61 ? 0.35 : s >= 41 ? 0.25 : 0.15);
  const finalPrice = (parseFloat(data.vehicle.fipe) || 0) * getPct(total);
  
  const col1 = CHECKLIST_MASTER_LIST.slice(0, 13);
  const col2 = CHECKLIST_MASTER_LIST.slice(13, 26);
  const col3 = CHECKLIST_MASTER_LIST.slice(26, 39);

  return (
    <div className="bg-white text-black p-10 mx-auto text-[10px]" style={{ width: "210mm", minHeight: "297mm", fontFamily: "\"Inter\", \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif" }}>
      <MimicoHeader subtitulo="FORMULÁRIO IV" regional={data.agency.regional} />
      <div className="text-center font-bold text-[13px] uppercase mb-4 tracking-tighter text-black">
        LAUDO DE VISTORIA PARA ALIENAÇÃO DE {(!data.assetType || data.assetType === 'Veículo' || data.assetType === 'Automóvel') 
          ? 'AUTOMÓVEL/ÔNIBUS/CAMINHÃO/CORRELATOS' 
          : data.assetType === 'Embarcação' 
            ? 'EMBARCAÇÕES E MOTORES NÁUTICOS' 
            : 'AERONAVES E COMPONENTES'}
      </div>
      
      <div className="border border-black mb-2 overflow-hidden text-[10px] font-bold uppercase text-left">
        <p className="bg-gray-100 p-0.5 border-b border-black uppercase  text-black">1. INFORMAÇÕES DO ÓRGÃO</p>
        <div className="p-1 grid grid-cols-12 border-b border-black divide-x border-black text-black"><div className="col-span-6 text-black">ÓRGÃO: <span className="font-normal">{data.agency.nome}</span></div><div className="col-span-3 px-1 text-black">FONE: <span className="font-normal">{data.agency.fone}</span></div><div className="col-span-3 px-1 text-right text-black">DATA: <span className="font-normal">{data.date}</span></div></div>
        <div className="p-1 border-b border-black text-black text-black">PORTARIA: <span className="font-normal">{data.agency.portaria}</span></div>
        <div className="p-1 grid grid-cols-2 border-b border-black divide-x divide-black text-black"><div>PRESIDENTE: <span className="font-normal border-b border-dotted border-black">{data.agency.presidente}</span></div><div className="px-1 text-black text-black">1º MEMBRO: <span className="font-normal border-b border-dotted border-black">{data.agency.membro1}</span></div></div>
        <div className="p-1 grid grid-cols-2 divide-x divide-black text-black text-black"><div>2º MEMBRO: <span className="font-normal border-b border-dotted border-black">{data.agency.membro2}</span></div><div className="px-1 text-black text-black">DIOE: <span className="font-normal">{data.agency.dioe}</span></div></div>
      </div>

      <div className="border border-black mb-2 overflow-hidden text-left  font-bold text-black text-black">
        <p className="bg-gray-100 p-0.5 border-b border-black uppercase  font-bold text-black">2. DADOS DO VEÍCULO</p>
        <div className="grid grid-cols-12 border-b border-black divide-x border-black text-black text-black">
          <div className="col-span-5 p-1 text-black text-black">Marca/Modelo: <span className="font-normal uppercase">{data.vehicle.modelo}</span></div>
          <div className="col-span-3 p-1 text-black text-black">Placa: <span className="font-normal uppercase">{data.vehicle.placa}</span></div>
          <div className="col-span-4 p-1 text-black text-black">Chassi: <span className="font-normal font-mono uppercase">{data.vehicle.chassi}</span></div>
        </div>
        <div className="grid grid-cols-12 divide-x border-black text-black text-black">
          <div className="col-span-3 p-1 text-black text-black">Ano Fab/Mod.: <span className="font-normal">{data.vehicle.ano}</span></div>
          <div className="col-span-3 p-1 text-black  text-black">Nº Motor: <span className="font-normal font-mono uppercase">{data.vehicle.motor}</span></div>
          <div className="col-span-2 p-1 text-black text-black">Cor: <span className="font-normal uppercase">{data.vehicle.cor}</span></div>
          <div className="col-span-4 p-1 text-black text-black">Nº Patrimônio (GPM): <span className="font-normal font-mono uppercase">{data.vehicle.patrimonio}</span></div>
        </div>
      </div>
      
      <div className="border border-black mb-2 text-left font-bold uppercase text-[10px] text-black">
        <p className="bg-gray-100 p-0.5 border-b border-black  text-black">3. ENDEREÇO FÍSICO ONDE ENCONTRA-SE O VEÍCULO</p>
        <div className="grid grid-cols-12 border-b border-black divide-x border-black text-black">
           <div className="col-span-9 p-1 text-black uppercase text-black flex items-center">Rua: 
             {readOnly ? <span className="font-normal text-black ml-1 whitespace-nowrap overflow-hidden text-ellipsis">{data.vehicle.endereco.rua}</span> : <input type="text" className="w-full bg-transparent border-b border-dotted border-black ml-1  font-normal focus:outline-none uppercase text-black text-[10px]" value={data.vehicle.endereco.rua || ''} onChange={e => update({...data, vehicle: {...data.vehicle, endereco: {...data.vehicle.endereco, rua: e.target.value}}})} />}
           </div>
           <div className="col-span-3 p-1 text-black text-left uppercase text-black flex items-center">Nº: 
             {readOnly ? <span className="font-normal text-black ml-1">{data.vehicle.endereco.num}</span> : <input type="text" className="w-full bg-transparent border-b border-dotted border-black ml-1  font-normal focus:outline-none uppercase text-black text-[10px]" value={data.vehicle.endereco.num || ''} onChange={e => update({...data, vehicle: {...data.vehicle, endereco: {...data.vehicle.endereco, num: e.target.value}}})} />}
           </div>
        </div>
        <div className="grid grid-cols-12 divide-x border-black text-black text-black">
           <div className="col-span-6 p-1 text-black text-left uppercase text-black flex items-center">Bairro: 
             {readOnly ? <span className="font-normal text-black ml-1 whitespace-nowrap overflow-hidden text-ellipsis">{data.vehicle.endereco.bairro}</span> : <input type="text" className="w-full bg-transparent border-b border-dotted border-black ml-1  font-normal focus:outline-none uppercase text-black text-[10px]" value={data.vehicle.endereco.bairro || ''} onChange={e => update({...data, vehicle: {...data.vehicle, endereco: {...data.vehicle.endereco, bairro: e.target.value}}})} />}
           </div>
           <div className="col-span-6 p-1 text-black text-left text-black uppercase text-black flex items-center">Cidade: 
             {readOnly ? <span className="font-normal text-black ml-1 whitespace-nowrap overflow-hidden text-ellipsis">{data.vehicle.endereco.cidade}</span> : <input type="text" className="w-full bg-transparent border-b border-dotted border-black ml-1  font-normal focus:outline-none uppercase text-black text-[10px]" value={data.vehicle.endereco.cidade || ''} onChange={e => update({...data, vehicle: {...data.vehicle, endereco: {...data.vehicle.endereco, cidade: e.target.value}}})} />}
           </div>
        </div>
      </div>

      <div className="border border-black mb-0 overflow-hidden text-black text-black text-black text-black text-black"><p className="bg-gray-100 p-0.5 font-bold  border-b border-black uppercase leading-none text-black text-black">4. CHECK-LIST</p><div className="grid grid-cols-3 divide-x border-black border-b border-black text-black text-black"><ChecklistCol items={col1} laudoData={data} update={update} readOnly={readOnly} /><ChecklistCol items={col2} laudoData={data} update={update} readOnly={readOnly} /><ChecklistCol items={col3} laudoData={data} update={update} readOnly={readOnly} /></div><div className="p-1 min-h-[45px]  border-b border-black font-bold uppercase text-left text-black text-black"><p className="font-bold  mb-0.5 italic text-black text-black">Descrição:</p><textarea disabled={readOnly} className="w-full h-12 bg-transparent border-none focus:outline-none  font-normal italic leading-tight resize-none text-black text-black text-black text-black text-[10px]" value={data.description} onChange={e=>update({...data, description: e.target.value})} /></div></div>

      <div className="border-x-2 border-b-2 border-black mt-2 overflow-hidden text-left font-bold uppercase text-black text-black text-black">
        <p className="bg-gray-100 p-0.5 font-bold  border-b border-black text-center uppercase text-black text-black">5. AVALIAÇÃO</p>
        <div className="grid grid-cols-12 border-b border-black divide-x border-black h-8 items-center  text-center bg-white text-black text-black">
           <div className="col-span-4 h-full flex items-center justify-center text-black text-black">RECUPERÁVEL: ( {data.classification === 'RECUPERÁVEL' ? 'X' : ' '} )</div>
           <div className="col-span-4 h-full flex items-center justify-center bg-gray-50 border-x border-black font-bold uppercase text-black text-black">NOTA: <span className="font-bold underline px-1 text-black">{total}</span></div>
           <div className="col-span-4 h-full flex items-center justify-center text-black text-black">SUCATA: ( {data.classification === 'SUCATA' ? 'X' : ' '} )</div>
        </div>
        <div className="grid grid-cols-12 border-b border-black divide-x border-black h-8 items-center  text-center text-black text-black text-black">
           <div className="col-span-4 h-full flex items-center justify-center font-bold text-black text-black">FIPE R$: <span className="font-normal ml-1 text-black text-black">{data.vehicle.fipe}</span></div>
           <div className="col-span-5 h-full flex items-center justify-center italic  normal-case text-black text-black">Mês e Ano Ref. FIPE: SET/25</div>
           <div className="col-span-3 h-full flex items-center justify-center font-bold text-black text-black">% DA FIPE: {(getPct(total)*100).toFixed(0)}%</div>
        </div>
        <div className="grid grid-cols-12 divide-x border-black h-10 items-center  font-bold text-black text-black">
           <div className="col-span-6 h-full flex items-center px-1 leading-tight uppercase text-black font-bold text-black text-black">*Na falta da FIPE usar o Valor de Mercado R$:</div>
           <div className="col-span-6 h-full flex items-center justify-end bg-gray-200 px-2  font-black text-black text-black">
             PREÇO MÍNIMO R$: <span className="font-bold border border-black bg-white px-2 ml-1 shadow-sm font-normal text-[10px] text-black">{finalPrice.toLocaleString('pt-BR', {minimumFractionDigits: 2})}</span>
           </div>
        </div>
      </div>

      <div className="mt-2 space-y-2 text-black text-black text-black">
         <div className="group relative text-black text-black">
            <p className="font-bold uppercase  mb-0.5 text-black text-black">6. FOTO DO CHASSI</p>
            <div className="border border-black h-24 flex items-center justify-center bg-gray-50 relative overflow-hidden">
               {data.chassisPhoto ? <img src={data.chassisPhoto} alt="Chassis" className="w-full h-full object-cover" /> : <Camera size={24} className="text-gray-300" />}
               <div className="absolute bottom-1 right-2 bg-white/90 border border-black px-2  font-mono font-bold text-black text-black uppercase">{data.vehicle.chassi}</div>
            </div>
         </div>
         <div className="group relative text-black text-black text-black">
            <p className="font-bold uppercase  mb-0.5 text-black text-black">6.1 FOTO DO Nº DO MOTOR</p>
            <div className="border border-black h-24 flex items-center justify-center bg-gray-50 relative overflow-hidden">
               {data.motorPhoto ? <img src={data.motorPhoto} alt="Motor" className="w-full h-full object-cover" /> : <Camera size={24} className="text-gray-300" />}
               <div className="absolute bottom-1 right-2 bg-white/90 border border-black px-2  font-mono font-bold text-black text-black uppercase">{data.vehicle.motor}</div>
            </div>
         </div>
      </div>
    </div>
  );
};

interface DigitalIdModalProps {
  vehicle: any | null;
  isDark: boolean;
  onClose: () => void;
  onUpdate: (id: string, updates: any) => void;
}

const DigitalIdModal: React.FC<DigitalIdModalProps> = ({ vehicle, isDark, onClose, onUpdate }) => {
  const [localFileira, setLocalFileira] = React.useState(vehicle?.fileira || '');
  const [localPosicao, setLocalPosicao] = React.useState(vehicle?.posicao || '');
  const [isSaving, setIsSaving] = React.useState(false);

  const saveToFirestore = async (field: 'fileira' | 'posicao', value: string) => {
    if (!vehicle?.id) return;
    setIsSaving(true);
    try {
      await updateDoc(doc(db, "vehicles", vehicle.id), { [field]: value });
      onUpdate(vehicle.id, { [field]: value });
    } catch (err) {
      console.error(`Erro ao atualizar ${field}:`, err);
    } finally {
      setIsSaving(false);
    }
  };

  const dotsPattern = React.useMemo(() => {
    if (!vehicle) return Array(36).fill(false);
    // Use placard characters to generate a semi-stable "random" pattern
    const seed = vehicle.placa || 'DEFAULT';
    return Array.from({ length: 36 }).map((_, i) => {
      const charCode = seed.charCodeAt(i % seed.length);
      return ((charCode * (i + 1)) % 10) > 4;
    });
  }, [vehicle]);
  
  if (!vehicle) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="absolute inset-0" onClick={onClose}></div>
      <div className={`relative w-full max-w-sm rounded-[2.5rem] border overflow-hidden p-8 flex flex-col items-center animate-in zoom-in-95 duration-500 ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100 shadow-2xl'}`}>
        <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-6 shadow-lg ${isDark ? 'bg-blue-900/30 text-blue-400' : 'bg-blue-50 text-[#003B95]'}`}>
          <QrCode size={32} />
        </div>
        
        <h3 className={`text-2xl font-black mb-1 uppercase tracking-tighter ${isDark ? 'text-white' : 'text-slate-900'}`}>{vehicle.placa}</h3>
        <p className={`text-[10px] font-bold uppercase tracking-[0.2em] mb-8 ${isDark ? 'text-slate-500' : 'text-gray-400'}`}>Identidade Digital Argos</p>
        
        <div className={`w-48 h-48 rounded-3xl p-4 mb-8 bg-white flex items-center justify-center border-4 ${isDark ? 'border-slate-800 shadow-inner' : 'border-gray-50'}`}>
           <div className="w-full h-full border-2 border-dashed border-gray-200 rounded-xl relative flex items-center justify-center overflow-hidden bg-white">
             <div className="grid grid-cols-6 gap-1 opacity-90 p-2">
                {dotsPattern.map((show, i) => (
                  <div key={i} className={`w-3 h-3 rounded-sm ${show ? 'bg-slate-900' : 'bg-transparent'}`} />
                ))}
             </div>
             <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-10 h-10 bg-white border-2 border-slate-900 rounded-lg flex items-center justify-center shadow-md">
                   <div className="w-6 h-6 bg-[#003B95] rounded-md" />
                </div>
             </div>
           </div>
        </div>

        <div className="w-full space-y-4 mb-8">
           <div className="flex justify-between items-center text-xs">
              <span className="font-bold opacity-40 uppercase">Modelo</span>
              <span className={`font-black ${isDark ? 'text-white' : 'text-slate-900'}`}>{vehicle.modelo}</span>
           </div>
           <div className="flex justify-between items-center text-xs">
              <span className="font-bold opacity-40 uppercase">Chassi</span>
              <span className={`font-mono font-bold ${isDark ? 'text-blue-400' : 'text-blue-600'}`}>{vehicle.chassi}</span>
           </div>
           
           {/* Localização Pátio */}
           <div className={`p-4 rounded-2xl border ${isDark ? 'bg-slate-800/50 border-slate-700' : 'bg-orange-50/50 border-orange-100'}`}>
             <div className="flex items-center justify-between mb-3">
               <div className="flex items-center gap-2 text-[10px] font-black text-orange-600 uppercase tracking-widest">
                 <MapPin size={12} />
                 <span>Posição no Pátio</span>
               </div>
               {isSaving && <div className="text-[8px] font-black text-orange-400 animate-pulse uppercase">Salvando...</div>}
             </div>
             <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-[8px] font-black uppercase opacity-40 mb-1">Fileira</label>
                  <input 
                    type="text"
                    value={localFileira}
                    onChange={(e) => setLocalFileira(e.target.value.toUpperCase())}
                    onBlur={(e) => saveToFirestore('fileira', e.target.value)}
                    className={`w-full bg-transparent border-b font-black text-xs p-1 outline-none transition-colors ${isDark ? 'border-slate-700 focus:border-orange-500 text-white' : 'border-orange-200 focus:border-orange-500 text-slate-900'}`}
                    placeholder="---"
                  />
               </div>
               <div>
                  <label className="block text-[8px] font-black uppercase opacity-40 mb-1">Posição</label>
                  <input 
                    type="text"
                    value={localPosicao}
                    onChange={(e) => setLocalPosicao(e.target.value.toUpperCase())}
                    onBlur={(e) => saveToFirestore('posicao', e.target.value)}
                    className={`w-full bg-transparent border-b font-black text-xs p-1 outline-none transition-colors ${isDark ? 'border-slate-700 focus:border-orange-500 text-white' : 'border-orange-200 focus:border-orange-500 text-slate-900'}`}
                    placeholder="---"
                  />
               </div>
             </div>
           </div>
           <div className="flex justify-between items-center text-xs">
              <span className="font-bold opacity-40 uppercase">Status</span>
              <span className={`font-bold px-2 py-0.5 rounded ${isDark ? 'bg-blue-900/40 text-blue-300' : 'bg-blue-50 text-blue-700'}`}>ATIVO</span>
           </div>
        </div>

        <button onClick={onClose} className="w-full py-4 bg-slate-900 dark:bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl active:scale-95 transition-all">
          Fechar Identidade
        </button>
      </div>
    </div>
  );
};

const PrintPreviewModal = ({ showPreview, laudoData, isDark, setShowPreview, previewPage, setPreviewPage, setLaudoData }: { 
  showPreview: boolean, 
  laudoData: any, 
  isDark: boolean, 
  setShowPreview: any, 
  previewPage: number, 
  setPreviewPage: any,
  setLaudoData: any
}) => {
  if (!showPreview || !laudoData) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 md:p-10 lg:p-20 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
      <div className="absolute inset-0" onClick={() => setShowPreview(false)}></div>
      <div className={`relative w-full max-w-5xl h-full flex flex-col items-center animate-in zoom-in-95 duration-500 overflow-hidden rounded-[3rem] border-4 ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100 shadow-2xl'}`}>
        <header className="flex justify-between items-center w-full p-8 border-b border-slate-800/20">
          <div className="flex items-center space-x-4">
            <div className="w-10 h-10 rounded-2xl bg-slate-800 flex items-center justify-center shadow-lg">
              <FileText size={20} className="text-slate-400" />
            </div>
            <div>
              <h3 className={`text-xl font-black uppercase tracking-tighter ${isDark ? 'text-white' : 'text-slate-900'}`}>Pré-visualização de Impressão</h3>
              <p className="text-xs font-bold text-slate-500 uppercase tracking-[0.2em]">Confira os dados antes de finalizar</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <div className="flex bg-slate-800/50 p-1 rounded-2xl border border-slate-700/30">
              <button onClick={() => setPreviewPage(1)} className={`px-6 py-2 rounded-xl text-xs font-black uppercase transition-all ${previewPage === 1 ? 'bg-slate-700 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}>Form I</button>
              <button onClick={() => setPreviewPage(2)} className={`px-6 py-2 rounded-xl text-xs font-black uppercase transition-all ${previewPage === 2 ? 'bg-slate-700 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}>Form IV</button>
            </div>
            <button onClick={() => setShowPreview(false)} className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-800/50 text-slate-400 hover:bg-red-900/40 hover:text-red-400 transition-all">
              <Trash2 size={18} />
            </button>
          </div>
        </header>
        <div className="flex-1 w-full overflow-auto p-4 md:p-10 bg-slate-950/20 scrollbar-hide">
           <div className="bg-white shadow-[0_50px_100px_rgba(0,0,0,0.5)] p-4 ring-2 ring-black min-w-[210mm] w-max mx-auto h-max">
             {previewPage === 1 ? <MimicoFormI data={laudoData} update={setLaudoData} readOnly={true} /> : <MimicoFormIV data={laudoData} update={setLaudoData} readOnly={true} />}
           </div>
        </div>
        <footer className="p-8 w-full border-t border-slate-800/20 flex justify-center">
           <button onClick={() => setShowPreview(false)} className="px-10 py-4 bg-slate-800 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-slate-700 transition-all">Voltar para Edição</button>
        </footer>
      </div>
    </div>
  );
};

const AnalyticsHeader = ({ inspectedResults, isDark }: { inspectedResults: any[], isDark: boolean }) => {
  const [view, setView] = useState<'score' | 'fipe'>('score');

  const scoreData = [
    { name: 'Péssimo', count: inspectedResults.filter(r => (r.nota || 0) >= 0 && (r.nota || 0) <= 40).length, color: '#ef4444' },
    { name: 'Regular', count: inspectedResults.filter(r => (r.nota || 0) > 40 && (r.nota || 0) <= 60).length, color: '#f59e0b' },
    { name: 'Bom', count: inspectedResults.filter(r => (r.nota || 0) > 60 && (r.nota || 0) <= 90).length, color: '#10b981' },
    { name: 'Ótimo', count: inspectedResults.filter(r => (r.nota || 0) > 90).length, color: '#059669' },
  ];

  const fipeData = [
    { name: '15% FIPE', count: inspectedResults.filter(r => r.class !== 'SUCATA' && (r.nota || 0) <= 40).length, color: '#ef4444' },
    { name: '25% FIPE', count: inspectedResults.filter(r => r.class !== 'SUCATA' && (r.nota || 0) > 40 && (r.nota || 0) <= 60).length, color: '#f16b20' },
    { name: '35% FIPE', count: inspectedResults.filter(r => r.class !== 'SUCATA' && (r.nota || 0) > 60 && (r.nota || 0) <= 90).length, color: '#10b981' },
    { name: '50% FIPE', count: inspectedResults.filter(r => r.class !== 'SUCATA' && (r.nota || 0) > 90).length, color: '#059669' },
  ];

  const chartData = view === 'score' ? scoreData : fipeData;

  const sucataCount = inspectedResults.filter(r => r.class === 'SUCATA' || r.class === 'INSERVÍVEL').length;
  const recuperavelCount = inspectedResults.filter(r => r.class === 'RECUPERÁVEL' || r.class === 'BOM' || r.class === 'REGULAR' || r.class === 'ALB').length;

  return (
    <div className="space-y-6 mb-8 mt-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Bento 1: Classification Chart - Enlarged */}
        <div className={`md:col-span-2 p-6 rounded-3xl border flex flex-col justify-between shadow-sm relative overflow-hidden group transition-all duration-300 hover:shadow-lg ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100 hover:border-blue-100'}`}>
          <div className="relative z-10 w-full h-full flex flex-col">
            <div className="flex justify-between items-start mb-2">
              <div className="flex flex-col">
                <h3 className={`font-semibold tracking-tight uppercase text-xs ${isDark ? 'text-slate-400' : 'text-gray-500'}`}>
                  {view === 'score' ? 'Distribuição de Pontuação' : 'Avaliação por % FIPE'}
                </h3>
                <div className="flex items-center gap-1 mt-1">
                  <button 
                    onClick={() => setView('score')}
                    className={`text-[10px] px-2 py-0.5 rounded-full font-bold transition-colors ${view === 'score' ? (isDark ? 'bg-blue-600 text-white' : 'bg-[#003B95] text-white') : (isDark ? 'text-slate-500 hover:text-slate-300' : 'text-gray-400 hover:text-gray-600')}`}
                  >
                    PONTOS
                  </button>
                  <button 
                    onClick={() => setView('fipe')}
                    className={`text-[10px] px-2 py-0.5 rounded-full font-bold transition-colors ${view === 'fipe' ? (isDark ? 'bg-blue-600 text-white' : 'bg-[#003B95] text-white') : (isDark ? 'text-slate-500 hover:text-slate-300' : 'text-gray-400 hover:text-gray-600')}`}
                  >
                    % FIPE
                  </button>
                </div>
              </div>
              <div className={`p-2 rounded-xl ${isDark ? 'bg-blue-900/30' : 'bg-blue-50'}`}>
                <Activity className={isDark ? 'text-blue-400' : 'text-[#003B95]'} size={18} />
              </div>
            </div>
            
            <div className="flex-1 h-[180px] mt-2">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 5, right: 5, left: -30, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? '#334155' : '#f1f5f9'} />
                  <XAxis 
                    dataKey="name" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fontSize: 10, fill: isDark ? '#94a3b8' : '#64748b' }}
                  />
                  <YAxis 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fontSize: 10, fill: isDark ? '#94a3b8' : '#64748b' }}
                  />
                  <Tooltip 
                    cursor={{ fill: isDark ? '#1e293b' : '#f8fafc' }}
                    contentStyle={{ 
                      backgroundColor: isDark ? '#0f172a' : '#fff', 
                      borderColor: isDark ? '#334155' : '#e2e8f0',
                      borderRadius: '12px',
                      fontSize: '12px',
                      color: isDark ? '#f1f5f9' : '#1e293b'
                    }}
                  />
                  <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                    {chartData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className={`absolute -bottom-8 -right-8 w-40 h-40 rounded-full opacity-[0.03] group-hover:opacity-10 transition-opacity duration-500 pointer-events-none blur-3xl ${isDark ? 'bg-blue-500' : 'bg-[#003B95]'}`}></div>
        </div>

        {/* Bento 2: Combined Status (Recuperáveis + Sucata) */}
        <div className={`md:col-span-1 p-6 rounded-3xl border flex flex-col justify-between shadow-sm relative overflow-hidden group transition-all duration-300 hover:shadow-lg ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100 hover:border-blue-100'}`}>
          <div className="relative z-10 h-full flex flex-col justify-between">
            <div className="flex justify-between items-start mb-4">
              <h3 className={`font-semibold tracking-tight uppercase text-xs ${isDark ? 'text-slate-400' : 'text-gray-500'}`}>Destinação de Status</h3>
              <div className={`p-2 rounded-xl ${isDark ? 'bg-slate-100' : 'bg-gray-50'} dark:bg-slate-800`}>
                <BarChart2 className={isDark ? 'text-slate-400' : 'text-gray-500'} size={18} />
              </div>
            </div>
            
            <div className="space-y-6">
              <div className="flex items-center justify-between">
                <div className="flex flex-col">
                  <span className={`text-4xl font-black tracking-tighter ${isDark ? 'text-emerald-400' : 'text-emerald-600'}`}>{recuperavelCount}</span>
                  <span className={`text-[10px] font-bold uppercase tracking-wider ${isDark ? 'text-slate-500' : 'text-gray-400'}`}>Recuperáveis</span>
                </div>
                <div className={`p-3 rounded-2xl ${isDark ? 'bg-emerald-900/20' : 'bg-emerald-50'}`}>
                  <Wrench className={isDark ? 'text-emerald-400' : 'text-emerald-600'} size={20} />
                </div>
              </div>
              
              <div className="flex items-center justify-between">
                <div className="flex flex-col">
                  <span className={`text-4xl font-black tracking-tighter ${isDark ? 'text-red-400' : 'text-red-600'}`}>{sucataCount}</span>
                  <span className={`text-[10px] font-bold uppercase tracking-wider ${isDark ? 'text-slate-500' : 'text-gray-400'}`}>Sucata / Inservível</span>
                </div>
                <div className={`p-3 rounded-2xl ${isDark ? 'bg-red-900/20' : 'bg-red-50'}`}>
                  <AlertTriangle className={isDark ? 'text-red-400' : 'text-red-600'} size={20} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const DashboardSummary = ({ frota, inspectedResults, isDark, setActiveTab }: { frota: any[], inspectedResults: any[], isDark: boolean, setActiveTab: (tab: string) => void }) => {
  const totalFleet = frota.length;
  const evaluatedPlacas = new Set(inspectedResults.map(r => r.placa));
  const evaluatedCount = inspectedResults.length;
  const availableToEvaluateCount = frota.filter(v => !evaluatedPlacas.has(v.placa)).length;
  const progressPct = totalFleet > 0 ? Math.round((evaluatedCount / (availableToEvaluateCount + evaluatedCount)) * 100) : 0;
  
  const data = [
    { name: 'Aguardando', value: availableToEvaluateCount, color: isDark ? '#374151' : '#e5e7eb' },
    { name: 'Avaliados', value: evaluatedCount, color: '#003580' },
  ];

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 mb-8 mt-2">
      <div className={`lg:col-span-8 p-6 rounded-lg shadow-sm border flex flex-col md:flex-row items-center gap-8 ${isDark ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200'}`}>
        <div className="w-48 h-48 relative shrink-0">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={data}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={2}
                dataKey="value"
                stroke="none"
              >
                {data.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: isDark ? '#1f2937' : '#ffffff', 
                  borderRadius: '4px', 
                  border: isDark ? '1px solid #374151' : '1px solid #e5e7eb',
                  fontSize: '12px',
                  color: isDark ? '#f9fafb' : '#111827'
                }}
              />
            </PieChart>
          </ResponsiveContainer>
          <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
            <span className={`text-4xl font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>{progressPct}%</span>
            <span className="text-xs text-slate-500 mt-1">Status</span>
          </div>
        </div>

        <div className="flex-1 w-full space-y-4">
          <div>
            <h4 className={`text-lg font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>Percentual avaliado</h4>
            <p className="text-slate-500 text-sm">Cobertura de vistorias técnicas na frota ativa.</p>
          </div>
          
          <div className="flex flex-col space-y-3 pt-2">
            {data.map((item) => (
              <div key={item.name} className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <span className={`text-sm ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>{item.name}</span>
                </div>
                <div className="flex items-center space-x-3 w-3/5">
                  <div className={`h-2 flex-1 rounded-sm overflow-hidden ${isDark ? 'bg-slate-700' : 'bg-slate-100'}`}>
                    <div 
                      className="h-full" 
                      style={{ 
                        width: `${totalFleet > 0 && !isNaN(item.value) ? (item.value / totalFleet) * 100 : 0}%`,
                        backgroundColor: item.color 
                      }}
                    ></div>
                  </div>
                  <span className={`text-sm font-semibold w-8 text-right ${isDark ? 'text-slate-200' : 'text-slate-900'}`}>{item.value}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="lg:col-span-4 flex flex-col gap-4">
        <div 
          onClick={() => setActiveTab('selecao')}
          className={`flex-1 p-6 rounded-lg shadow-sm border cursor-pointer transition-all hover:scale-[1.02] active:scale-[0.98] ${isDark ? 'bg-slate-800 border-slate-700 hover:border-blue-500' : 'bg-white border-slate-200 hover:border-blue-300 shadow-blue-500/5'}`}
        >
          <div className="flex items-center justify-between mb-2">
            <p className="text-sm font-semibold text-slate-500">Veículos à avaliar</p>
            <Activity className={isDark ? 'text-slate-400' : 'text-blue-600'} size={20} />
          </div>
          <p className={`text-3xl font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>{availableToEvaluateCount}</p>
        </div>
        
        <div 
          onClick={() => setActiveTab('dashboard')}
          className={`flex-1 p-6 rounded-lg shadow-sm border cursor-pointer transition-all hover:scale-[1.02] active:scale-[0.98] ${isDark ? 'bg-blue-900 border-blue-800 text-blue-100 hover:bg-blue-800' : 'bg-[#003B95] border-[#003B95] text-white hover:bg-[#002e75] shadow-blue-900/10'}`}
        >
          <div className="flex items-center justify-between mb-2">
            <p className="text-sm font-semibold text-white/80">Vistorias Concluídas</p>
            <CheckCircle className="text-white/60" size={20} />
          </div>
          <p className="text-3xl font-bold text-white">{evaluatedCount}</p>
        </div>
      </div>
    </div>
  );
};

