  enderecoPatio?: string; // ENDEREÇO DO PÁTIO
  municipio: string; // MUNICÍPIO
  fileira?: string; // FILEIRA
  posicao?: string; // POSIÇÃO/NÚMERO
  uploadedAt?: any;
