  const handleBulkDeleteVehicles = async () => {
    if (selectedVehicles.length === 0) return;
    setLoadingTask({ type: 'exclusion', message: 'Excluindo veículos...', progress: 0 });
    try {
      const chunks = [];
      for (let i = 0; i < selectedVehicles.length; i += 500) {
        chunks.push(selectedVehicles.slice(i, i + 500));
      }

      let processedCount = 0;
      for (const chunk of chunks) {
        const batch = writeBatch(db);
        for (const id of chunk) {
          if (id && id.length > 5) {
            batch.delete(doc(db, "vehicles", id));
          }
        }
        await batch.commit();
        processedCount += chunk.length;
        setLoadingTask({ type: 'exclusion', message: 'Excluindo veículos...', progress: (processedCount / selectedVehicles.length) * 100 });
      }

      setFrota(prev => prev.filter(v => !selectedVehicles.includes(v.id || '')));
      setSelectedVehicles([]);
      setIsDeleteMode(false);
      setShowBulkDeleteConfirm(false);
    } catch (e) {
      handleFirestoreError(e, OperationType.DELETE, "vehicles");
    } finally {
      setLoadingTask(null);
    }
  };

  const handleBulkDeleteYards = async () => {
    if (selectedYardsForBulk.length === 0) return;
    setLoadingTask({ type: 'exclusion', message: 'Apagando pátios...', progress: 0 });
    try {
      const vehiclesToDelete = frota.filter(v => 
        selectedYardsForBulk.includes(String(v.municipio || 'NÃO INFORMADO').toUpperCase())
      );
      
      if (vehiclesToDelete.length === 0) {
        setSelectedYardsForBulk([]);
        setShowYardDeleteConfirm(false);
        setLoadingTask(null);
        return;
      }

      const vehicleIds = vehiclesToDelete.map(v => v.id).filter(id => id && id.length > 0);
      const vehiclePlacas = vehiclesToDelete.map(v => v.placa).filter(p => p && p.length > 0);
      
      const chunks = [];
      for (let i = 0; i < vehicleIds.length; i += 500) {
        chunks.push(vehicleIds.slice(i, i + 500));
      }

      let processedCount = 0;
      for (const chunk of chunks) {
        const batch = writeBatch(db);
        for (const id of chunk) {
          batch.delete(doc(db, "vehicles", id as string));
        }

        // Also try to find and delete inspections if any
        // Note: This is simplified. Ideally we'd query by plate if we had many, 
        // but for a few yards deleting the vehicles is the main goal.
        // We'll filter the currently loaded inspections to find ones to delete.
        const inspectionsToDelete = inspectedResults.filter(r => vehiclePlacas.includes(r.placa));
        for (const insp of inspectionsToDelete) {
          if (insp.id) {
            batch.delete(doc(db, "inspections", insp.id));
          }
        }

        await batch.commit();
        processedCount += chunk.length;
        setLoadingTask({ type: 'exclusion', message: 'Apagando pátios...', progress: (processedCount / vehicleIds.length) * 100 });
      }

      setFrota(prev => prev.filter(v => !selectedYardsForBulk.includes(String(v.municipio || 'NÃO INFORMADO').toUpperCase())));
      setInspectedResults(prev => prev.filter(r => !vehiclePlacas.includes(r.placa)));
      setSelectedYardsForBulk([]);
      setShowYardDeleteConfirm(false);
      toast.success(`Pátios removidos com sucesso (${vehiclesToDelete.length} veículos e vistorias vinculadas)`);
    } catch (err) {
      console.error("Erro ao apagar pátios:", err);
      toast.error("Erro ao apagar pátios do servidor");
    } finally {
      setLoadingTask(null);
    }
  };

  const exportLaudosAsAnexoJ = () => {
    const evaluatedPlacas = new Set(inspectedResults.map(r => r.placa));
    const vehiclesWithLaudos = frota.filter(v => evaluatedPlacas.has(v.placa));
    
    if (vehiclesWithLaudos.length === 0) {
      alert("Nenhum veículo com laudo pronto para exportar.");
      return;
    }

    setLoadingTask({ type: 'loading', message: 'Gerando Anexo J...' });

    setTimeout(() => {
      try {
        const data = vehiclesWithLaudos.map(v => {
          const laudo = inspectedResults.find(r => r.placa === v.placa);
          const fullData = laudo?.fullData || {};
          
          const formatCurrency = (val: any) => {
            if (!val) return '';
            if (typeof val === 'number') return `R$ ${val.toLocaleString('pt-BR', {minimumFractionDigits: 2})}`;
            const num = parseFloat(String(val).replace(/[^\d.,]/g, '').replace(',', '.'));
            if (!isNaN(num)) return `R$ ${num.toLocaleString('pt-BR', {minimumFractionDigits: 2})}`;
            return val;
          };

          const endereco = v.endereco ? `${v.endereco.rua || ''}, ${v.endereco.num || ''} - ${v.endereco.bairro || ''}`.replace(/^[,\s-]+|[,\s-]+$/g, '') : '';

          return {
            'ORGÃO': v.orgao || 'CBMPR',
            'PLACA': v.placa || '',
            'MARCA/MODELO': v.modelo || '',
            'TIPO': v.tipo || fullData.assetType || '',
            'AVALIAÇÃO': laudo?.class || '',
            'CHASSI': v.chassi || '',
            'NÚM. DO MOTOR': v.motor || '',
            'ANO': v.ano || '',
            'COMB.': v.comb || fullData.vehicle?.comb || '',
            'PATRIMÔNIO': v.patrimonio || '',
            'COR/DOC.': v.cor || '',
            ' ': '', // Coluna L
            '  ': '', // Coluna M
            'ORIGEM': v.origem || '',
            'RENAVAM': v.renavam || '',
            'FIPE': formatCurrency(v.fipe),
            '% DA FIPE': laudo?.valuationPercent ? `${laudo.valuationPercent}%` : '',
            'PREÇO MÍNIMO': formatCurrency(laudo ? (parseCurrency(v.fipe) * ((laudo.valuationPercent || 0) / 100)) : 0),
            'SITUAÇÃO DETRAN': v.situacaoDetran || 'REGULAR',
            'ENDEREÇO DO PÁTIO': v.enderecoPatio || endereco,
            'MUNICÍPIO': v.municipio || ''
          };
        });

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Base Anexo J");
        XLSX.writeFile(wb, "Anexo_J_Veiculos_Laudados.xlsx");
      } finally {
        setLoadingTask(null);
      }
    }, 100);
  };

  const [exportingPDF, setExportingPDF] = useState(false);

