    const generateSinglePDF = async (data: any, returnBlob: boolean = false) => {
    setLaudoDataToPrint(data);
    await new Promise(r => setTimeout(r, 800)); // waitForDom
    const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
    const addFormToDoc = async (elementId: string, isFirst: boolean) => {
      const form = document.getElementById(elementId);
      if (!form) return;
      try {
        const imgData = await toJpeg(form, {
          quality: 1.0, pixelRatio: 2, width: form.scrollWidth, height: form.scrollHeight,
          style: { transform: "scale(1)", margin: "0" }, backgroundColor: "#ffffff"
        });
        if (!isFirst) doc.addPage();
        const pdfPageWidth = doc.internal.pageSize.getWidth();
        const pdfPageHeight = doc.internal.pageSize.getHeight();
        const imgProps = doc.getImageProperties(imgData);
        const ratio = Math.min(pdfPageWidth / imgProps.width, pdfPageHeight / imgProps.height);
        doc.addImage(imgData, "JPEG", (pdfPageWidth - imgProps.width * ratio) / 2, 0, imgProps.width * ratio, imgProps.height * ratio);
      } catch (err) {
        console.error(err); throw err;
      }
    };
    await addFormToDoc("pdf-auto-form-1", true);
    await addFormToDoc("pdf-auto-form-2", false);
    
    if (returnBlob) {
      return {
        blob: doc.output('blob'),
        filename: `SESP-CBMPR_LAUDO_${data?.vehicle?.placa || "VEICULO"}.pdf`
      };
    } else {
      doc.save(`SESP-CBMPR_LAUDO_${data?.vehicle?.placa || "VEICULO"}.pdf`);
    }
  };

